function safeRead(key, fallback) {
  try { const value = JSON.parse(localStorage.getItem(key) || "null"); return value ?? fallback; } catch { return fallback; }
}
function parseGp(value) {
  if (typeof value === "number") return value;
  const s = String(value ?? "").trim().toLowerCase().replace(/,/g, "");
  if (!s) return NaN;
  const m = s.match(/^(-?\d+(?:\.\d+)?)([kmb])?$/);
  if (!m) return Number(s);
  const multipliers = { k: 1e3, m: 1e6, b: 1e9 };
  return Number(m[1]) * (multipliers[m[2]] || 1);
}
function fuzzyScore(query, text) {
  const q = query.toLowerCase().trim(), t = text.toLowerCase();
  if (!q) return 0;
  if (t === q) return 10000;
  if (t.startsWith(q)) return 8000 - t.length;
  if (t.includes(q)) return 6000 - t.indexOf(q);
  let qi = 0, gaps = 0;
  for (let i = 0; i < t.length && qi < q.length; i++) { if (t[i] === q[qi]) qi++; else gaps++; }
  if (qi === q.length) return 3000 - gaps;
  let dist = 0;
  for (let i = 0; i < Math.min(4, q.length); i++) if (!t.includes(q.slice(i, i + 2))) dist++;
  return dist <= 2 ? 1000 - t.length : -1;
}
function fuzzyItems(items, query, limit = 10) {
  const q = query.trim();
  if (!q) return [];
  return items.map(x => ({ x, score: fuzzyScore(q, x.name) })).filter(a => a.score >= 0).sort((a,b) => b.score - a.score).slice(0, limit).map(a => a.x);
}
function enrich(row, mapping, daily = {}) {
  const m = mapping[row.id] || {};
  const buy = Number(row.high ?? 0), sell = Number(row.low ?? 0), tax = taxFor(sell), margin = sell - buy - tax;
  const d = daily[row.id] || daily[String(row.id)] || {};
  const volume = Number(d.volume ?? ((d.highPriceVolume || 0) + (d.lowPriceVolume || 0)));
  const limit = Number(m.limit || 0), potentialProfit = margin * limit, alch = Number(m.highalch ?? m.highAlch ?? 0) || 0;
  return {...row,...m,buy,sell,tax,margin,roi:buy?margin/buy*100:0,volume,limit,potentialProfit,limitProfit:potentialProfit,alch,buyUpdated:row.highTime?row.highTime*1000:null,sellUpdated:row.lowTime?row.lowTime*1000:null,lastUpdated:Math.max(row.highTime||0,row.lowTime||0)*1000||null};
}
function addFlipScores(rows) {
  const valid = rows.filter(x=>x.buy>0&&x.sell>0&&x.margin>0);
  const maxRoi=Math.max(1,...valid.map(x=>Math.max(0,x.roi))), maxMargin=Math.max(1,...valid.map(x=>Math.max(0,x.margin))), maxVol=Math.max(1,...valid.map(x=>Math.max(0,x.volume)));
  return rows.map(x=>{
    const roiScore=Math.min(1,Math.max(0,x.roi)/maxRoi);
    const marginScore=Math.min(1,Math.max(0,x.margin)/maxMargin);
    const volumeScore=Math.min(1,Math.log10(1+Math.max(0,x.volume))/Math.log10(1+maxVol));
    const liquidityScore=x.limit>0?Math.min(1,Math.max(0,x.volume)/x.limit):0;
    const score=x.margin<=0?0:Math.round((roiScore*.35+marginScore*.30+volumeScore*.25+liquidityScore*.10)*100);
    return {...x,flipScore:Math.max(0,Math.min(100,score))};
  });
}
function normalize24h(data) {
  if (!data) return {};
  if (Array.isArray(data)) return Object.fromEntries(data.map(x=>[x.id,x]));
  if (data.data && typeof data.data==='object') return data.data;
  return data;
}

async function api(path) {
  const res = await fetch(`${API}${path}`, { headers: { "User-Agent": "OSRSFlipIt/1.0" } });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
  return res.json();
}
