function NotificationPopover({alerts,clear,openItem,close}){return <div className="notificationPopover"><div className="popoverHead"><strong>Notifications</strong><button onClick={close}><X size={16}/></button></div>{alerts.length?<div className="popoverList">{alerts.slice(0,10).map(a=><button key={a.id} onClick={()=>{openItem(a.itemId);close()}}><span className="ndot"/><div><strong>{a.name}</strong><small>{a.metric} hit {num(a.target)}{a.metric==="roi"?"%":" gp"}</small></div></button>)}</div>:<div className="popoverEmpty"><Check size={17}/> You're all caught up.</div>}{alerts.length>0&&<button className="clearPopover" onClick={clear}>Clear all notifications</button>}</div>}
